{
  "case_id": "xsu_sg_014_occupational_injury_opinion",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Svaret gengiver korrekt begge kritiske elementer (påvirkning af evnen til at arbejde og om funktionsevnen er så nedsat, at et studiejob ikke kan varetages). Det angiver også korrekt, at udtalelsen er vejledende og ikke binder Udbetaling Danmark. Ingen væsentlige juridiske fejl."},
    "c02_required_elements_complete": {"label": "met", "reason": "Begge kritiske elementer fra rubrikken er med: graden af påvirkning af arbejdsevnen og vurderingen af, om et studiejob ikke kan have. De understøttende elementer om dokumentgrundlaget og manglende undersøgelse er ikke kritiske."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer begge dele af spørgsmålet: hvad udtalelsen skal belyse, og om Udbetaling Danmark er bundet af den."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde (hverken bestemmelse, lov eller vejledning)."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så kildens gyldighed kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Alle udsagn har dækning i vejledningens afsnit 5.1.3.3. Svaret tilføjer ingen ny regel, betingelse eller myndighed."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "Den krævede kvalifikation er med: udtalelsen er vejledende, og Udbetaling Danmark er ikke bundet af den. Svaret nævner også, at den indgår i den samlede vurdering."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er kort og konsistent. Konklusionen om, at udtalelsen ikke er bindende, følger af, at den er vejledende og indgår i den samlede vurdering."},
    "c10_legal_modality_precision": {"label": "met", "reason": "Modaliteten er præcis: udtalelsen 'skal belyse' de to forhold, og den er 'vejledende' og 'ikke bindende'. Svaret gør intet skønsmæssigt absolut."}
  },
  "xhaile_coverage": {
    "A68": {"label": "partial", "reason": "Svaret dækker de to vurderingspunkter (påvirkning af evnen til at arbejde, og om et studiejob ikke kan have) og at udtalelsen er vejledende. Det nævner ikke, at Udbetaling Danmark kan indhente udtalelsen, at den bygger på den foreliggende dokumentation uden undersøgelse af den uddannelsessøgende, eller at styrelsen betaler udgifterne."}
  },
  "overall_notes": "Materielt korrekt og komplet svar på de kritiske elementer, men helt uden kildeangivelse. Derfor C04 not_met og C05/C06 not_assessable. Svaret udelader de understøttende elementer om dokumentgrundlag og manglende undersøgelse."
}

